@import "tailwindcss";
@import "@fontsource-variable/geist";
@import "@fontsource/instrument-serif/400.css";
@import "@fontsource/instrument-serif/400-italic.css";

@source "./**/*.{ts,tsx}";

@theme {
  --font-sans: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Instrument Serif", Georgia, "Times New Roman", serif;

  --color-ink: #0c0a10;
  --color-ink-2: #14111a;
  --color-ink-3: #1d1824;
  --color-cream: #fff6ee;
  --color-sand: #e9d6c8;
  --color-dune: #b39a8b;
  --color-ash: #7c6d66;
  --color-ember: #ff7a1a;
  --color-ember-2: #ff9a3c;
  --color-blush: #ffb39b;
  --color-rose: #f06a8a;
  --color-plum: #5b2a66;

  --shadow-glow: 0 0 0 1px rgb(255 122 26 / 0.35), 0 12px 48px -12px rgb(255 122 26 / 0.55);
  --shadow-card: 0 1px 0 0 rgb(255 255 255 / 0.06) inset, 0 24px 60px -30px rgb(0 0 0 / 0.8);

  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-out-quart: cubic-bezier(0.25, 1, 0.5, 1);
}

:root {
  color-scheme: dark;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 5rem;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  font-family: var(--font-sans);
  color: var(--color-cream);
  background: var(--color-ink);
  overflow-x: clip;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

::selection {
  background: rgb(255 122 26 / 0.35);
  color: var(--color-cream);
}

:focus-visible {
  outline: 2px solid var(--color-ember-2);
  outline-offset: 3px;
  border-radius: 4px;
}

.font-display {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: -0.015em;
}

/* Film grain overlay for the whole page */
.grain {
  position: fixed;
  z-index: 60;
  inset: 0;
  pointer-events: none;
  opacity: 0.05;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-size: 256px 256px;
}

/* Text gradient used for accent words */
.text-ember-gradient {
  background: linear-gradient(105deg, #fff1e0 0%, #ffb39b 40%, #ff7a1a 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* Scroll reveal */
[data-reveal] {
  opacity: 0;
  transform: translate3d(0, 24px, 0);
  transition:
    opacity 0.9s var(--ease-out-expo),
    transform 0.9s var(--ease-out-expo);
  transition-delay: var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}

[data-reveal="left"] {
  transform: translate3d(-24px, 0, 0);
}

[data-reveal="scale"] {
  transform: scale(0.96);
}

[data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* Hero entrance */
@keyframes rise {
  from {
    opacity: 0;
    transform: translate3d(0, 28px, 0);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes glow-breathe {
  0%,
  100% {
    opacity: 0.55;
    transform: scale(1);
  }
  50% {
    opacity: 0.9;
    transform: scale(1.06);
  }
}

@keyframes marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

@keyframes shimmer {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}

@keyframes caret {
  0%,
  49% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}

@keyframes progress {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

.anim-rise {
  animation: rise 1.1s var(--ease-out-expo) both;
  animation-delay: var(--delay, 0ms);
}

.anim-fade {
  animation: fade 1.4s var(--ease-out-quart) both;
  animation-delay: var(--delay, 0ms);
}

.anim-glow {
  animation: glow-breathe 6s ease-in-out infinite;
}

.anim-marquee {
  animation: marquee 40s linear infinite;
}

.anim-caret {
  animation: caret 1s steps(1) infinite;
}

.anim-progress {
  transform-origin: left;
  animation: progress var(--duration, 3200ms) linear both;
}

.skeleton {
  background: linear-gradient(
    90deg,
    rgb(255 255 255 / 0.06) 0%,
    rgb(255 255 255 / 0.14) 50%,
    rgb(255 255 255 / 0.06) 100%
  );
  background-size: 200% 100%;
  animation: shimmer 1.8s linear infinite;
}

/* Accordion height animation via grid rows */
.accordion-panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.45s var(--ease-out-expo);
}

.accordion-panel[data-open="true"] {
  grid-template-rows: 1fr;
}

.accordion-panel > div {
  overflow: hidden;
}

/* Hero parallax layer */
.parallax {
  transform: translate3d(0, calc(var(--scroll, 0) * 0.25px), 0) scale(1.08);
  will-change: transform;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .anim-rise,
  .anim-fade,
  .anim-glow,
  .anim-marquee,
  .anim-caret,
  .anim-progress,
  .skeleton {
    animation: none;
  }

  .anim-rise,
  .anim-fade {
    opacity: 1;
    transform: none;
  }

  .anim-progress {
    transform: scaleX(1);
  }

  .parallax {
    transform: scale(1.02);
  }

  .accordion-panel {
    transition: none;
  }

  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

