/* Accordion height animation via grid rows */
.accordion-panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.45s var(--ease-out-expo);
}

.accordion-panel[data-open="true"] {
  grid-template-rows: 1fr;
}

.accordion-panel > div {
  overflow: hidden;
}

/* Hero parallax layer */
.parallax {
  transform: translate3d(0, calc(var(--scroll, 0) * 0.25px), 0) scale(1.08);
  will-change: transform;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .anim-rise,
  .anim-fade,
  .anim-glow,
  .anim-marquee,
  .anim-caret,
  .anim-progress,
  .skeleton {
    animation: none;
  }

  .anim-rise,
  .anim-fade {
    opacity: 1;
    transform: none;
  }

  .anim-progress {
    transform: scaleX(1);
  }

  .parallax {
    transform: scale(1.02);
  }

  .accordion-panel {
    transition: none;
  }

  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
