import type { CSSProperties } from "react";

import type { CampaignImage } from "../lib/images";

type CampaignImageProps = {
  image: CampaignImage;
  className?: string;
  imgClassName?: string;
  sizes?: string;
  priority?: boolean;
  style?: CSSProperties;
  /** Decorative images inside a text section get an empty alt. */
  decorative?: boolean;
};

export function CampaignPicture({
  image,
  className = "",
  imgClassName = "",
  sizes = "100vw",
  priority = false,
  style,
  decorative = false,
}: CampaignImageProps) {
  return (
    <div
      className={`relative overflow-hidden bg-ink-2 ${className}`}
      style={{
        backgroundImage: `url(${image.placeholder})`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        ...style,
      }}
    >
